import java.util.*;
class Q{String s(boolean p,String I){var l=I.lines().toList();int h=l.size(),w=l.get(0).length(),n=w*h,a=p?1:4,b=p?3:10;var v=new int[n*5];Arrays.fill(v,1<<30);var q=new PriorityQueue<Long>();q.add(4L);v[4]=0;while(!q.isEmpty()){long e=q.poll();int c=(int)(e>>32),s=(int)e,d=s%5,o=s/5,x=o%w,y=o/w;if(c>v[s])continue;if(o==n-1)return""+c;for(int t=0;t<4;t++)if(d>3||t%2!=d%2){int C=c;for(int i=1;i<=b;i++){int X=x+i*(t%2<1?1-t:0),Y=y+i*(t%2>0?2-t:0);if(X<0||Y<0||X>=w||Y>=h)break;C+=l.get(Y).charAt(X)-48;int S=(Y*w+X)*5+t;if(i>=a&&C<v[S]){v[S]=C;q.add((long)C<<32|S);}}}}return"";}}
